(x, y, t) => {
  let nx = x / 480, ny = y / 240;
  let u = 0, v = 0, w = 0;
  for (let i = 0; i < 9; i++) {
    let a = i * 0.698 + t * 0.12 * ((i % 3) - 1);
    let f = 18 + 4 * Math.sin(t * 0.25 + i * 0.7);
    let wave = Math.sin(nx * f * Math.cos(a) + ny * f * Math.sin(a) + t * 0.5 + i * 1.8);
    let ph = i * 2.094;
    u += wave * Math.cos(ph);
    v += wave * Math.cos(ph + 2.094);
    w += wave * Math.cos(ph + 4.189);
  }
  let mag = Math.sqrt(u * u + v * v + w * w) / 9;
  let r1 = u * (1 - mag) - v * 0.7;
  let r2 = v * (1 - mag) - w * 0.6;
  let r3 = w * (1 - mag) - u * 0.5;
  let coarse = Math.sin(r1 * 3 + r2 * 1.5);
  let fine = Math.sin(r2 * 5 - r3 * 2.5);
  let detail = Math.sin((r1 + r3) * 8);
  let p = coarse * 0.5 + fine * 0.3 + detail * 0.2;
  let s1 = 1 / (1 + Math.exp(-p * 6));
  let s2 = 1 / (1 + Math.exp(-fine * 4));
  let hue = t * 0.05 + p * 0.5;
  let cr = 0.5 + 0.45 * Math.sin(hue * 6.28);
  let cg = 0.5 + 0.45 * Math.sin(hue * 6.28 + 2.094);
  let cb = 0.5 + 0.45 * Math.sin(hue * 6.28 + 4.189);
  cr = s1 * cr + (1 - s1) * (0.04 + 0.08 * s2);
  cg = s1 * cg + (1 - s1) * (0.06 + 0.12 * s2);
  cb = s1 * cb + (1 - s1) * (0.12 + 0.18 * s2);
  let lum = (cr + cg + cb) / 3;
  cr = lum + (cr - lum) * 1.5;
  cg = lum + (cg - lum) * 1.5;
  cb = lum + (cb - lum) * 1.5;
  cr = Math.pow(Math.max(0, Math.min(1, cr)), 0.85);
  cg = Math.pow(Math.max(0, Math.min(1, cg)), 0.85);
  cb = Math.pow(Math.max(0, Math.min(1, cb)), 0.85);
  return [cr * 255, cg * 255, cb * 255];
}
